// Green Moon catalog — production bridge to the existing working admin/backend.
// The customer site keeps its existing design/content. /admin is redirected to the
// already-working admin Worker. No GPS/location functionality is included.

const BACKEND = "https://green-moon-products.greenmoon-eg.workers.dev";

const SITE_B64 = "";
const PRODUCT_B64 = "";
const ADMIN_B64 = "";
const AUDIO_B64 = "";

function decodeB64Utf8(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
  return new TextDecoder("utf-8").decode(bytes);
}
const SITE_HTML = decodeB64Utf8(SITE_B64);
const PRODUCT_HTML = decodeB64Utf8(PRODUCT_B64);
const ADMIN_HTML = decodeB64Utf8(ADMIN_B64);
const GM_NATURE_AUDIO = "data:audio/mpeg;base64," + AUDIO_B64;

const HTML_HEADERS = {
  "Content-Type":"text/html; charset=UTF-8",
  "Cache-Control":"no-store",
  "X-Content-Type-Options":"nosniff",
  "Referrer-Policy":"strict-origin-when-cross-origin"
};

function html(s) {
  return s.replaceAll("__GM_NATURE_AUDIO__", GM_NATURE_AUDIO);
}

function apiResponseHeaders() {
  return {
    "Access-Control-Allow-Origin":"*",
    "Access-Control-Allow-Methods":"GET,HEAD,POST,PUT,PATCH,DELETE,OPTIONS",
    "Access-Control-Allow-Headers":"Content-Type,x-admin-token,Authorization",
    "Access-Control-Max-Age":"86400"
  };
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;

    // IMPORTANT: the working admin is the backend admin, not the old embedded demo.
    if (path === "/admin" || path === "/admin/") {
      return Response.redirect(BACKEND + "/admin" + url.search, 302);
    }

    // Keep API requests on the same public site URL for compatibility with any
    // existing relative /api/* calls, but proxy them to the working backend.
    if (path === "/api" || path.startsWith("/api/")) {
      if (request.method === "OPTIONS") {
        return new Response(null, { status:204, headers:apiResponseHeaders() });
      }
      try {
        const target = BACKEND + path + url.search;
        const init = {
          method: request.method,
          headers: new Headers(request.headers),
          redirect: "follow"
        };
        if (request.method !== "GET" && request.method !== "HEAD") {
          init.body = request.body;
        }
        const upstream = await fetch(target, init);
        const headers = new Headers(upstream.headers);
        for (const [k,v] of Object.entries(apiResponseHeaders())) headers.set(k,v);
        headers.set("Cache-Control","no-store");
        return new Response(upstream.body, {
          status:upstream.status,
          statusText:upstream.statusText,
          headers
        });
      } catch (e) {
        return new Response(JSON.stringify({
          ok:false,
          error:"تعذر الاتصال بخدمة المتجر",
          detail:String(e?.message || e)
        }), {
          status:502,
          headers:{"Content-Type":"application/json; charset=utf-8", ...apiResponseHeaders()}
        });
      }
    }

    if (path.startsWith("/assets/")) {
      const file = path.slice("/assets/".length);
      if (!/^[A-Za-z0-9._-]+$/.test(file)) return new Response("Not found",{status:404});
      const urls = [
        "https://raw.githubusercontent.com/mohammedelgarhy90-rgb/green-moon-products/main/" + encodeURIComponent(file),
        "https://raw.githubusercontent.com/mohammedelgarhy90-rgb/green-moon-products/main/assets/" + encodeURIComponent(file)
      ];
      let r = null;
      for (const u of urls) {
        try {
          const x = await fetch(u, { cf:{cacheTtl:86400,cacheEverything:true} });
          if (x.ok) { r=x; break; }
        } catch (_) {}
      }
      if (!r) return new Response("Asset not found",{status:404});
      const h = new Headers(r.headers);
      h.set("Cache-Control","public, max-age=86400");
      return new Response(r.body,{status:r.status,headers:h});
    }

    if (path === "/favicon.ico") return new Response("",{status:204});
    if (/^\/product\/(?:\d+)(?:\/)?$/.test(path) || path === "/product/11.html") {
      return new Response(html(PRODUCT_HTML),{headers:HTML_HEADERS});
    }
    return new Response(html(SITE_HTML),{headers:HTML_HEADERS});
  }
};
